fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    if len == 0 {
        return (Vec::new(), Vec::new());
    } else if len == 1 {
        return (Vec::new(), a);
    } else {
        // Split the array into the first element and the rest
        let first = vec![a[0]];
        let second = a[1..].to_vec(); // Take the rest of the elements
        return (first, second);
    }
}